go version && cd /tmp && mkdir -p b64probe && cd b64probe && cat > main.go <<'EOF'
package main

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"io"
	"strings"
)

func try(name, in string) {
	r := io.NopCloser(strings.NewReader(in))
	_ = r
	// streaming std
	b, err := io.ReadAll(base64.NewDecoder(base64.StdEncoding, strings.NewReader(in)))
	fmt.Printf("%-20q stream-std:  %q err=%v\n", in, b, err)
	// DecodeString std after TrimSpace
	s, err2 := base64.StdEncoding.DecodeString(strings.TrimSpace(in))
	fmt.Printf("%-20q trim-std:    %q err=%v\n", in, s, err2)
	_ = bytes.TrimSpace
}

func main() {
	try("x", "aGVsbG8=")
	try("x", "aGVsbG8=\n")
	try("x", "aGVs\nbG8=")
	try("x", "aGVsbG8=\nd29ybGQ=\n")
	try("x", "aGVsbG8")
	try("x", "aGVsbG")
	try("x", "Yj0=")
	try("x", "!!!invalid!!!")
	try("x", "")
}
EOF
go mod init probe >/dev/null 2>&1; go run main.go

cd /tmp/b64probe && cat > n2.go <<'EOF'
package main

import (
	"encoding/base64"
	"fmt"
	"io"
	"strings"
)

func main() {
	for _, in := range []string{"aGVs\nbG8=", "YQ==\nYQ==", "aGVs\n\n", "aGVsbG8=\nd29ybGQ=\n"} {
		// std streaming
		b, err := io.ReadAll(base64.NewDecoder(base64.StdEncoding, strings.NewReader(in)))
		fmt.Printf("%q => %q %v\n", in, b, err)
		// raw streaming
		b2, err2 := io.ReadAll(base64.NewDecoder(base64.RawStdEncoding, strings.NewReader(in)))
		fmt.Printf("%q raw => %q %v\n", in, b2, err2)
	}
}
EOF
go run n2.go

cd /tmp/b64probe && cat > n3.go <<'EOF'
package main

import (
	"encoding/base64"
	"fmt"
	"strings"
)

func dec(in string) {
	s := strings.TrimSpace(in)
	if r := len(s) % 4; r != 0 {
		s += strings.Repeat("=", 4-r)
	}
	b, err := base64.StdEncoding.DecodeString(s)
	fmt.Printf("%-14q -> %q err=%v\n", in, b, err)
}

func main() {
	for _, in := range []string{"a", "====", "Yg", "Yg=", "Yg==", "Yg===", "=Yg==", "Y=g=", "aGVsbG8==", "YQ==x", "Pz4_Pz8="} {
		dec(in)
	}
}
EOF
go run n3.go
